interface Handler {
  setNext(handler: Handler): Handler;
  handle(request: string): string | null;
}
class ConcreteHandlerA implements Handler {
  private next: Handler | null = null;
  setNext(handler: Handler) { this.next = handler; return handler; }
  handle(request: string) { if (request.includes('A')) return 'A'; return this.next ? this.next.handle(request) : null; }
}

class HandlerA { next?: any; handle(req: any) { if (req.type === 'a') return 'A'; return this.next?.handle(req); } }
class HandlerB { next?: any; handle(req: any) { if (req.type === 'b') return 'B'; return this.next?.handle(req); } }
const chain = new HandlerA();
chain.next = new HandlerB();
const result = chain.handle({ type: 'b' });

// Version A: centralized dispatcher
function handleRequest(req: any) {
  switch (req.type) {
    case 'a': return 'A';
    case 'b': return 'B';
    default: return null;
  }
}

// Version B: handler objects linked into a sequence
interface Handler { setNext(h: Handler): Handler; handle(req: any): string | null; }
class AHandler implements Handler { private next?: Handler; setNext(h: Handler){ this.next = h; return h; } handle(req:any){ if(req.type==='a') return 'A'; return this.next?.handle(req) ?? null; } }
